import Image from "next/image";
import React from "react";
import S from "./techParadigmStyles";

/* ── Default data (override via props) ───────────────────────────── */
const defaultData = {
  sectionTitle: "The New Tech Paradigm",
  image: {
    src: "/images/ai-tech-monitor.png",
    alt: "AI neural network on monitor",
  },
  topic: {
    title: "Artificial Intelligence",
    description:
      "On a global scale, AI is expected to drive a $15.7 trillion economic boost by 2030; specifically within India, Generative AI alone is forecasted to contribute up to $1.5 trillion to the GDP by 2030.",
    source: "Sources: PwC / EY India Report",
  },
  stats: [
    {
      value: "$15.7T",
      label: "Expected economic boost by 2030",
    },
    {
      value: "$1.5T",
      label: "Contribution to the GDP by 2030",
    },
  ],
};

/* ─────────────────────────────────────────────────────────────────
   TechParadigm
   Props:
     sectionTitle  — section heading (optional, uses default)
     image         — { src, alt }
     topic         — { title, description, source }
     stats         — [{ value, label }, ...]
──────────────────────────────────────────────────────────────────── */
const TechParadigm = ({
  sectionTitle = defaultData.sectionTitle,
  image = defaultData.image,
  topic = defaultData.topic,
  stats = defaultData.stats,
}) => {
  return (
    <section className={S.section}>
      {/* Section heading */}
      <h2 className={S.sectionTitle}>{sectionTitle}</h2>

      {/* White card */}
      <div className={S.card}>

        {/* Left — image */}
        <div className={S.imageWrapper}>
          <Image
            src={image.src}
            alt={image.alt}
            fill
            className={S.image}
            sizes="(max-width: 1024px) 100vw, 45vw"
          />
        </div>

        {/* Right — content */}
        <div className={S.contentWrapper}>

          {/* Top: title + description + source */}
          <div className={S.topContent}>
            <h3 className={S.topicTitle}>{topic.title}</h3>
            <p className={S.description}>{topic.description}</p>
            {topic.source && (
              <p className={S.source}>{topic.source}</p>
            )}
          </div>

          {/* Bottom: stats row */}
          {stats.length > 0 && (
            <div className={S.statsRow}>
              {stats.map((stat, i) => (
                <React.Fragment key={i}>
                  <div className={S.statItem}>
                    <p className={S.statValue}>{stat.value}</p>
                    <p className={S.statLabel}>{stat.label}</p>
                  </div>
                  {/* Vertical divider between stats */}
                  {i < stats.length - 1 && (
                    <div className={S.statDivider} />
                  )}
                </React.Fragment>
              ))}
            </div>
          )}
        </div>
      </div>
    </section>
  );
};

export default TechParadigm;
